 cells={(i,j) for i,row in enumerate(grid) for j,x in enumerate(row) if x==co}
 # expose cells with at least one orthogonal neighbor not in shape
 sh0=[(i,j) for i,j in cells if any((i+di,j+dj) not in cells for di,dj in [(-1,0),(1,0),(0,-1),(0,1)])]
 a=min(i for i,j in cells);b=min(j for i,j in cells)
 sh=[(i-a,j-b) for i,j in sh0]; mr=max(r for r,c in sh);mc=max(c for r,c in sh)
 out=[row[:] for row in grid]
 for i in range(h-mr):
  for j in range(w-mc):
   pts=[(i+r,j+c) for r,c in sh]
   if all(grid[r][c]==0 for r,c in pts):
    for r,c in pts:out[r][c]=co
 return out
